result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "cooldowns.py", "content": """"Tick-based ability cooldowns. No wall-clock time anywhere."""

_cooldowns: dict[str, int] = {}   # name -> length in ticks
_ready_at: dict[str, int] = {}    # name -> tick when usable again
_now: int = 0


def register(name: str, cooldown_ticks: int) -> None:
    if cooldown_ticks < 1:
        raise ValueError("cooldown_ticks must be >= 1")
    _cooldowns[name] = cooldown_ticks


def try_use(name: str) -> bool:
    if name not in _cooldowns:
        raise KeyError(f"unknown ability: {name!r}")
    if _ready_at.get(name, 0) <= _now:
        _ready_at[name] = _now + _cooldowns[name]
        return True
    return False


def tick() -> None:
    global _now
    _now += 1
